"""Aggregated storefront totals for staff dashboards."""

from __future__ import annotations

from app import orders, pricing, settings, tax


class Snapshot:
    def __init__(self, merchandise: float, count: int) -> None:
        self.merchandise = merchandise
        self.count = count

    def as_dict(self) -> dict:
        return {"merchandise": self.merchandise, "count": self.count}

    def empty(self) -> bool:
        return self.count == 0


def iter_counted_rows() -> list[dict]:
    return list(orders.list_orders())


def line_amount(item: dict) -> float:
    return float(item.get("price") or 0.0)


def quoted_line(item: dict) -> float:
    return pricing.quote_price(
        str(item.get("sku") or "widget"),
        int(item.get("qty", 1) or 1),
        float(item.get("price") or 0.0),
    )


def merchandise_total(rows: list[dict]) -> float:
    amount = 0.0
    for row in rows:
        for item in row.get("items") or []:
            amount += line_amount(item)
    return round(amount, 2)


def counted_rows() -> list[dict]:
    return iter_counted_rows()


def build_snapshot() -> dict:
    rows = counted_rows()
    merchandise = merchandise_total(rows)
    if settings.flag_enabled("include_tax_in_reports"):
        merchandise = tax.inclusive_total(merchandise)
    snap = Snapshot(merchandise, len(rows))
    return snap.as_dict()


def order_count() -> int:
    return len(counted_rows())


def average_ticket() -> float:
    rows = counted_rows()
    if not rows:
        return 0.0
    return round(merchandise_total(rows) / len(rows), 2)


def sku_units(sku: str) -> int:
    total = 0
    for row in counted_rows():
        for item in row.get("items") or []:
            if str(item.get("sku") or "") == sku:
                total += int(item.get("qty", 1) or 1)
    return total


def reset_store() -> None:
    return None

"""Internal journal for captured and voided payments."""

from __future__ import annotations


class JournalLine:
    def __init__(self, kind: str, user_id: int, amount: float, ref: str) -> None:
        self.kind = kind
        self.user_id = user_id
        self.amount = amount
        self.ref = ref

    def as_dict(self) -> dict:
        return {
            "kind": self.kind,
            "user_id": self.user_id,
            "amount": self.amount,
            "ref": self.ref,
        }

    def is_debit(self) -> bool:
        return self.kind in {"capture", "fee"}


_LINES: list[JournalLine] = []


def record_capture(user_id: int, amount: float, ref: str) -> JournalLine:
    line = JournalLine("capture", user_id, float(amount), ref)
    _LINES.append(line)
    return line


def record_void(user_id: int, amount: float, ref: str) -> JournalLine:
    line = JournalLine("void", user_id, float(amount), ref)
    _LINES.append(line)
    return line


def record_fee(user_id: int, amount: float, ref: str) -> JournalLine:
    line = JournalLine("fee", user_id, float(amount), ref)
    _LINES.append(line)
    return line


def lines_for(user_id: int) -> list[dict]:
    return [line.as_dict() for line in _LINES if line.user_id == user_id]


def lines_for_ref(ref: str) -> list[dict]:
    return [line.as_dict() for line in _LINES if line.ref == ref]


def captured_total(user_id: int | None = None) -> float:
    total = 0.0
    for line in _LINES:
        if user_id is not None and line.user_id != user_id:
            continue
        if line.kind == "capture":
            total += line.amount
        elif line.kind == "void":
            total -= line.amount
    return round(total, 2)


def has_capture(ref: str) -> bool:
    return any(line.kind == "capture" and line.ref == ref for line in _LINES)


def last_line() -> dict | None:
    if not _LINES:
        return None
    return _LINES[-1].as_dict()


def reset_store() -> None:
    _LINES.clear()

"""JWT helpers for access tokens."""

from datetime import datetime, timedelta, timezone

import jwt
from fastapi import HTTPException

SECRET = "dev-secret-do-not-use-in-prod"
ALGO = "HS256"


def create_token(user_id: int, expires_in_seconds: int = 3600) -> str:
    """Create a signed JWT access token."""
    payload = {
        "user_id": user_id,
        "exp": datetime.now(timezone.utc)
        + timedelta(seconds=expires_in_seconds),
    }
    return jwt.encode(payload, SECRET, algorithm=ALGO)


def decode_token(token: str) -> dict:
    """Decode a signed JWT and return its payload."""
    try:
        return jwt.decode(token, SECRET, algorithms=[ALGO])
    except jwt.InvalidSignatureError as exc:
        raise HTTPException(status_code=401, detail="invalid token signature") from exc


def get_current_user_id(token: str) -> int:
    """Return the user_id claim from a valid token."""
    payload = decode_token(token)
    return payload["user_id"]


def require_admin(token: str) -> int:
    """Ensure the caller is an admin; return the caller's user id."""
    payload = decode_token(token)
    if payload.get("role") != "admin":
        raise HTTPException(status_code=403, detail="admin required")
    return payload["user_id"]

"""Runtime flags, locales, and shop defaults."""

from __future__ import annotations

_DEFAULTS: dict[str, object] = {
    "timezone": "UTC",
    "currency": "USD",
    "tax_rate": 0.0,
    "mail_from": "receipts@example.com",
    "default_zone": "domestic",
    "loyalty_enabled": True,
    "webhooks_enabled": False,
}

_OVERRIDES: dict[str, object] = {}


class FeatureFlag:
    def __init__(self, name: str, enabled: bool = False) -> None:
        self.name = name
        self.enabled = enabled

    def enable(self) -> None:
        self.enabled = True

    def disable(self) -> None:
        self.enabled = False

    def is_on(self) -> bool:
        return bool(self.enabled)


_FLAGS: dict[str, FeatureFlag] = {
    "include_tax_in_reports": FeatureFlag("include_tax_in_reports", False),
    "signed_webhooks": FeatureFlag("signed_webhooks", True),
    "quiet_hours": FeatureFlag("quiet_hours", False),
}


def get_setting(key: str, default: object | None = None) -> object:
    if key in _OVERRIDES:
        return _OVERRIDES[key]
    if key in _DEFAULTS:
        return _DEFAULTS[key]
    return default


def set_setting(key: str, value: object) -> None:
    _OVERRIDES[key] = value


def clear_override(key: str) -> None:
    _OVERRIDES.pop(key, None)


def timezone() -> str:
    return str(get_setting("timezone", "UTC"))


def currency() -> str:
    return str(get_setting("currency", "USD"))


def tax_rate() -> float:
    return float(get_setting("tax_rate", 0.0) or 0.0)


def mail_from() -> str:
    return str(get_setting("mail_from", "receipts@example.com"))


def default_zone() -> str:
    return str(get_setting("default_zone", "domestic"))


def loyalty_enabled() -> bool:
    return bool(get_setting("loyalty_enabled", True))


def webhooks_enabled() -> bool:
    return bool(get_setting("webhooks_enabled", False))


def flag(name: str) -> FeatureFlag:
    if name not in _FLAGS:
        _FLAGS[name] = FeatureFlag(name, False)
    return _FLAGS[name]


def flag_enabled(name: str) -> bool:
    return flag(name).is_on()


def enable_flag(name: str) -> None:
    flag(name).enable()


def disable_flag(name: str) -> None:
    flag(name).disable()


def snapshot() -> dict[str, object]:
    data = dict(_DEFAULTS)
    data.update(_OVERRIDES)
    data["flags"] = {name: item.is_on() for name, item in _FLAGS.items()}
    return data


def reset_store() -> None:
    _OVERRIDES.clear()
    for item in _FLAGS.values():
        item.disable()
    _FLAGS["signed_webhooks"].enable()
